toolCalls.commandLine:
"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -Command '$root=(Resolve-Path .).Path; $out=Join-Path $root '"'dev-server.out.log'; "'$err=Join-Path $root '"'dev-server.err.log'; Remove-Item "'$out,$err -Force -ErrorAction SilentlyContinue; $p=Start-Process -FilePath node -ArgumentList @('"'scripts/run-with-esbuild.mjs','vite','--host','127.0.0.1','--port','4178') -WorkingDirectory "'$root -RedirectStandardOutput $out -RedirectStandardError $err -PassThru -WindowStyle Hidden; Start-Sleep -Seconds 8; @'"'
const { chromium } = require('playwright');
(async()=>{
 const browser=await chromium.launch({headless:true});
 const page=await browser.newPage();
 page.on('console', msg=>console.log('console', msg.type(), msg.text()));
 page.on('pageerror', err=>console.log('pageerror', err.stack||err.message));
 await page.goto('http://127.0.0.1:4178/', {waitUntil:'networkidle'});
 await page.getByRole('link', {name:'GPT-4o', exact:true}).click();
 await page.locator('.tile').first().click();
 await page.getByRole('button', {name:/Add to cart|Get it free/}).click();
 await page.waitForTimeout(1500);
 console.log('toast=', await page.getByRole('status').textContent());
 await browser.close();
})();
'@ | node -; '--- stderr ---'; Get-Content "'$err -Raw -ErrorAction SilentlyContinue; if($p -and -not $p.HasExited){ Stop-Process -Id $p.Id -Force }'

